:root {
  --multi-border: #223151;
  --multi-background: #D7D8DB;
  --multi-field-background: #E5E8EB;

  --multi-title-color: #246875;
  --multi-label-color: #246875;
  --multi-value-color: #000000;
  --multi-unit-color: #0A638F;

  --multi-scale: 1;
  --multi-layout-width: 200px;
  --multi-frame-border: 1px;
  --multi-frame-radius: 5px;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.multi-widget,
.multi-widget *,
.multi-widget::before,
.multi-widget::after {
  box-sizing: border-box;
}

.multi-widget {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
  user-select: none;
  opacity: var(--w-opacity, 1);
}

.multi-card {
  position: absolute;
  inset: 0;
  overflow: hidden;

  border-radius: var(--multi-frame-radius);
  background: var(--multi-background);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.50),
    inset 0 -1px 0 rgba(85, 93, 105, 0.12);
}

.multi-card::after {
  content: "";
  position: absolute;
  inset: 0;
  box-sizing: border-box;

  border:
    var(--multi-frame-border)
    solid
    var(--multi-border);

  border-radius: inherit;
  pointer-events: none;
}

.multi-layout {
  position: absolute;
  left: 50%;
  top: 50%;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;

  width: var(--multi-layout-width);
  height: auto;
  padding: 6px 11px;

  transform:
    translate(-50%, -50%)
    scale(var(--multi-scale));

  transform-origin: center;
}

.multi-title {
  display: block;
  flex: 0 0 auto;

  width: max-content;
  height: 18px;
  margin: 0;
  padding: 0;

  color: var(--multi-title-color);

  font-family:
    "Bahnschrift",
    "Segoe UI",
    Arial,
    sans-serif;

  font-size: 16px;
  font-weight: 700;
  font-style: italic;
  font-kerning: normal;
  line-height: 18px;

  letter-spacing: 0;
  word-spacing: 0;
  text-align: center;
  white-space: nowrap;
}

/* Distribución original para las filas con nombre. */
.multi-rows {
  display: grid;
  grid-template-columns:
    max-content
    minmax(64px, max-content)
    max-content;

  align-items: center;
  justify-content: center;
  column-gap: 7px;
  row-gap: 5px;

  width: max-content;
}

/* Si ninguna fila tiene nombre, solo quedan valor y unidad. */
.multi-rows.multi-without-labels {
  grid-template-columns:
    minmax(64px, max-content)
    max-content;
}

/* Filas sin nombre dentro de un conjunto mixto. */
.multi-unlabeled-row {
  grid-column: 1 / -1;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.multi-label {
  margin: 0;
  padding: 0;

  color: var(--multi-unit-color);

  font-family:
    "Bahnschrift",
    "Segoe UI",
    Arial,
    sans-serif;

  font-size: 14px;
  font-weight: 600;
  font-style: normal;
  line-height: 18px;

  letter-spacing: 0;
  word-spacing: 0;
  text-align: center;
  white-space: nowrap;
}

.multi-field {
  display: flex;
  align-items: center;
  justify-content: center;

  min-width: 64px;
  height: 22px;
  padding: 0 8px;

  border: 1px solid #738594;
  border-radius: 3px;
  background: var(--multi-field-background);

  box-shadow:
    inset 0 1px 2px rgba(34, 49, 81, 0.10),
    inset 0 -1px 0 rgba(255, 255, 255, 0.40);
}

.multi-value,
.multi-unit {
  display: block;

  font-family:
    "IBM Plex Mono",
    Consolas,
    "Liberation Mono",
    monospace;

  font-size: 14px;
  font-weight: 600;
  font-style: normal;
  font-variant-numeric: tabular-nums;
  font-variant-ligatures: none;
  line-height: 18px;

  letter-spacing: 0;
  word-spacing: 0;
  text-align: center;
  white-space: nowrap;
}

.multi-value {
  color: var(--multi-value-color);
}

.multi-unit {
  color: var(--multi-unit-color);
}

