"use strict";

(function () {
  const BASE_WIDTH = 200;
  const CONTENT_MARGIN = 28;
  const NAMED_VALUES_PROPERTY = "vars";

  let container = null;
  let layout = null;
  let titleElement = null;
  let rowsElement = null;

  let lastUpdate = null;
  let resizeObserver = null;
  let pendingFrame = null;
  let currentSignature = "";
  let renderedRows = [];

  function normalizeSpaces(value) {
    return String(value)
      .replace(/\s+/g, " ")
      .trim();
  }

  function parseConfiguration(name) {
    const text =
      typeof name === "string"
        ? normalizeSpaces(name)
        : "";

    const parts = text.split("|");
    const title =
      normalizeSpaces(parts.shift() || "") || "Lecturas";

    const rows = [];
    const usedAliases = new Set();

    parts.forEach(function (part) {
      const definition = part.trim();
      if (!definition) return;

      const firstColon = definition.indexOf(":");
      if (firstColon < 0) return;

      const secondColon = definition.indexOf(
        ":",
        firstColon + 1
      );

      const alias = normalizeSpaces(
        definition.slice(0, firstColon)
      );

      if (!alias || usedAliases.has(alias)) return;

      const label = normalizeSpaces(
        secondColon >= 0
          ? definition.slice(firstColon + 1, secondColon)
          : definition.slice(firstColon + 1)
      );

      const unit = normalizeSpaces(
        secondColon >= 0
          ? definition.slice(secondColon + 1)
          : ""
      );

      /*
       * Las comillas vacías indican que no debe
       * mostrarse ningún nombre físico.
       *
       * Ejemplo:
       * principal:"":kg/h
       *
       * Un campo simplemente vacío conserva el
       * comportamiento anterior: muestra el alias.
       */
      const hideLabel = /^(?:"\s*"|“\s*”)$/.test(label);

      rows.push({
        alias: alias,
        label: hideLabel ? "" : (label || alias),
        unit: unit
      });

      usedAliases.add(alias);
    });

    if (rows.length === 0) {
      rows.push({
        alias: "principal",
        label: "Valor",
        unit: ""
      });
    }

    return {
      title: title,
      rows: rows
    };
  }

  function hasOwn(object, key) {
    return Object.prototype.hasOwnProperty.call(object, key);
  }

  function readNamedValue(w, alias) {
    const collection = w && w[NAMED_VALUES_PROPERTY];

    if (
      !collection ||
      typeof collection !== "object" ||
      Array.isArray(collection) ||
      !hasOwn(collection, alias)
    ) {
      return undefined;
    }

    const entry = collection[alias];

    if (
      entry !== null &&
      typeof entry === "object" &&
      hasOwn(entry, "value")
    ) {
      return entry.value;
    }

    if (
      typeof entry === "number" ||
      typeof entry === "string"
    ) {
      return entry;
    }

    return undefined;
  }

  function readValue(w, alias) {
    if (alias === "principal") {
      return w ? w.value : undefined;
    }

    return readNamedValue(w, alias);
  }

  function formatValue(raw) {
    let number = NaN;

    if (typeof raw === "number") {
      number = raw;
    } else if (
      typeof raw === "string" &&
      raw.trim() !== ""
    ) {
      number = Number(raw);
    }

    return Number.isFinite(number) ? String(number) : "—";
  }

  function buildRows(definitions) {
    const signature = JSON.stringify(definitions);

    if (signature === currentSignature) return;

    currentSignature = signature;
    renderedRows = [];

    const hasLabels = definitions.some(function (definition) {
      return definition.label !== "";
    });

    rowsElement.classList.toggle(
      "multi-without-labels",
      !hasLabels
    );

    const fragment = document.createDocumentFragment();

    definitions.forEach(function (definition) {
      const field = document.createElement("div");
      field.className = "multi-field";

      const value = document.createElement("span");
      value.className = "multi-value";
      value.textContent = "—";

      const unit = document.createElement("span");
      unit.className = "multi-unit";
      unit.textContent = definition.unit;

      field.appendChild(value);

      if (definition.label !== "") {
        // Fila original: nombre, valor y unidad.
        const label = document.createElement("div");
        label.className = "multi-label";
        label.textContent = definition.label;

        fragment.appendChild(label);
        fragment.appendChild(field);
        fragment.appendChild(unit);
      } else if (hasLabels) {
        /*
         * Conjunto mixto: centra esta fila completa
         * sin reservar una celda vacía para el nombre.
         */
        const row = document.createElement("div");
        row.className = "multi-unlabeled-row";

        row.appendChild(field);
        row.appendChild(unit);
        fragment.appendChild(row);
      } else {
        /*
         * Todas las filas sin nombre:
         * cuadrícula de dos columnas alineadas.
         */
        fragment.appendChild(field);
        fragment.appendChild(unit);
      }

      renderedRows.push({
        definition: definition,
        field: field,
        value: value
      });
    });

    rowsElement.replaceChildren(fragment);
  }

  function resizeLayout() {
    if (
      !container ||
      !layout ||
      !titleElement ||
      !rowsElement
    ) {
      return;
    }

    const availableWidth = container.clientWidth;
    const availableHeight = container.clientHeight;

    if (availableWidth <= 0 || availableHeight <= 0) {
      return;
    }

    const naturalWidth = Math.ceil(
      Math.max(
        BASE_WIDTH,
        titleElement.scrollWidth + CONTENT_MARGIN,
        rowsElement.scrollWidth + CONTENT_MARGIN
      )
    );

    container.style.setProperty(
      "--multi-layout-width",
      naturalWidth + "px"
    );

    const naturalHeight = layout.offsetHeight;

    if (naturalHeight <= 0) return;

    const scale = Math.min(
      availableWidth / naturalWidth,
      availableHeight / naturalHeight
    );

    container.style.setProperty(
      "--multi-scale",
      String(scale)
    );

    container.style.setProperty(
      "--multi-frame-border",
      scale + "px"
    );

    container.style.setProperty(
      "--multi-frame-radius",
      (5 * scale) + "px"
    );
  }

  function scheduleLayout() {
    if (pendingFrame !== null) return;

    pendingFrame = requestAnimationFrame(function () {
      pendingFrame = null;
      resizeLayout();
    });
  }

  function render(w) {
    if (!titleElement || !rowsElement) return;

    const config = parseConfiguration(w && w.name);

    titleElement.textContent = config.title;
    buildRows(config.rows);

    renderedRows.forEach(function (row) {
      const definition = row.definition;
      const raw = readValue(w, definition.alias);
      const text = formatValue(raw);

      row.value.textContent = text;

      // El alias solo se usa como descripción accesible.
      const accessibleName =
        definition.label || definition.alias;

      row.field.setAttribute(
        "aria-label",
        text === "—"
          ? accessibleName + ": sin valor numérico"
          : accessibleName + ": " + text +
            (definition.unit ? " " + definition.unit : "")
      );
    });

    scheduleLayout();
  }

  window.onWidgetUpdate = function (w) {
    lastUpdate = w;
    render(w);
  };

  function initialize() {
    container = document.querySelector(".multi-widget");
    layout = document.querySelector(".multi-layout");
    titleElement = document.querySelector(".multi-title");
    rowsElement = document.querySelector(".multi-rows");

    if (
      !container ||
      !layout ||
      !titleElement ||
      !rowsElement
    ) {
      return;
    }

    render(lastUpdate || window.WIDGET || null);
    resizeLayout();

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(scheduleLayout);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(scheduleLayout);
      resizeObserver.observe(container);
    } else {
      window.addEventListener("resize", scheduleLayout);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
